"},{"node":"useUpdateMemo","qualified_name":"bench-repo.web.src.hooks.useMemoQueries.useUpdateMemo","label":"Function","file":"web/src/hooks/useMemoQueries.ts","start_line":197,"end_line":251,"in_degree":4,"out_degree":0,"match_lines":[239],"source":"export function useUpdateMemo() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ update, updateMask }: { update: Partial<Memo>; updateMask: string[] }) => {
      const memo = await memoServiceClient.updateMemo({
        memo: create(MemoSchema, update as Record<string, unknown>),
        updateMask: create(FieldMaskSchema, { paths: updateMask }),
